#include <stdio.h>

int main() {
    int len1[] = {32, 32, 32, 32, 32};   /* RISC：定长 32 位 */
    int len2[] = {16, 32, 48, 16, 64};   /* CISC：变长 */
    int n = 5;
    int fixed1 = 1, fixed2 = 1;

    for (int i = 1; i < n; i++) {
        if (len1[i] != len1[0]) fixed1 = 0;  /* 是否所有指令等长 */
        if (len2[i] != len2[0]) fixed2 = 0;
    }

    printf("RISC 指令字长序列: ");
    for (int i = 0; i < n; i++) printf("%d ", len1[i]);
    printf("-> 定长? %s\n", fixed1 ? "是(RISC)" : "否");

    printf("CISC 指令字长序列: ");
    for (int i = 0; i < n; i++) printf("%d ", len2[i]);
    printf("-> 定长? %s\n", fixed2 ? "是(RISC)" : "否(CISC)");
    return 0;
}
